const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const d = $input.first().json.d;
const status = (d.status || []).map(s => `• <b>${esc(s.id)}</b> ${esc(s.title)}
   этап ${s.stage} · ${esc(s.stage_name)} · ${esc(s.status)} · $${Number(s.spent_usd).toFixed(2)} из $${Number(s.budget_usd).toFixed(0)}`).join('
') || '—';
const events = (d.events || []).slice(-10).map(e => `• ${esc(e.exp_id || 'ферма')}: ${esc(e.message)}`).join('
') || 'событий нет';
const text = `🌱 <b>Ферма · дайджест</b>

<b>Стартапы</b>
${status}

<b>За сутки</b>
${events}

Guardrails сработали: ${d.guard_fail}
Траты за месяц: $${Number(d.month_spend).toFixed(2)} из $${d.month_cap}
Агенты (подписка, эквивалент API): $${Number(d.agent_equiv).toFixed(2)}
Kill switch: ${d.kill === 'on' ? '🔴 ВКЛЮЧЁН' : 'выключен'}`;
return [{ json: { text } }];
